const crypto = require('node:crypto')
const path = require('node:path')
const { injectControlPolicy } = require('./control-policy')
const { configuredRoutes, resolveBoundCommand, resolveBoundFeedback } = require('./control-bound-protocol')
const { createDeviceAvailability } = require('./device-availability')
const { catalogBase, listCatalogDevices, listCatalogTargets } = require('./control-catalog')
const { contract } = require('./control-type-model')
const { parseVisualBindings } = require('./panel-visual-bindings')
const { instrumentTemplate } = require('./panel-template-instrumentation')
const { createPanelEditor } = require('./panel-editor-auth')
const { applyVisualBindings, editorConfig, getSnapshot } = require('./panel-visual-apply')
const { createGateway } = require('./gateway.cjs')
const { managedBridgeRevision } = require('./managed-bridge-revision')
const { createMeterRoom, createPanelMeter } = require('./panel-meter')
const { createXYSeriesRoom, createPanelXYSeries } = require('./panel-xy-series')
const { createMomentaryControls } = require('./panel-momentary')
const { runtimeFlowAccess } = require('./panel-runtime-flows')
const { createReadRefresh } = require('./panel-read-refresh')
const { createSubscriptionRecovery } = require('./panel-subscription-recovery')
const { createCatalogRecovery } = require('./panel-catalog-recovery')
const { attachTelemetryHooks } = require('./panel-telemetry-hooks')

let statestore
const authHandoffKey = crypto.randomBytes(32)
const gatewayHandoffs = new Map()
const editorHandoffs = new Map()
const panelLoginImage = path.join(__dirname, 'assets', 'panel-login-bg.png')

function authSignature (values) {
  return crypto.createHmac('sha256', authHandoffKey).update(JSON.stringify(values)).digest('hex')
}

function holdSessions (handoffs, id, signature, sessions) {
  const previous = handoffs.get(id)
  if (previous) clearTimeout(previous.timer)
  handoffs.delete(id)
  if (!sessions?.size) return
  const item = { signature, sessions }
  item.timer = setTimeout(() => { if (handoffs.get(id) === item) handoffs.delete(id) }, 60000)
  item.timer.unref?.()
  handoffs.set(id, item)
}

function takeSessions (handoffs, id, signature) {
  const item = handoffs.get(id)
  if (!item) return null
  clearTimeout(item.timer)
  handoffs.delete(id)
  return item.signature === signature ? item.sessions : null
}

function injectWidgetPolicy (format, templateScope, boundPanel) {
  if (templateScope === 'site:style' || templateScope === 'page:style') return format
  const rendered = instrumentTemplate(format).format
  const controls = Object.entries(boundPanel?.visual?.bindings || {})
    .map(([id, entry]) => ({ id, type: entry.type, mode: entry.mode }))
  const injected = injectControlPolicy(rendered, controls, boundPanel)
  if (!injected.includes('/* ui-control-panel-control-api-v1 */')) {
    throw new Error('Visual binding requires a supported Vue Options API template')
  }
  return injected
}

function getStateStore (RED) {
  if (statestore) return statestore
  try {
    const dashboardPath = require.resolve('@flowfuse/node-red-dashboard/nodes/store/state.js', {
      paths: [RED.settings.userDir || process.cwd()]
    })
    statestore = require(dashboardPath)
  } catch (error) {
    RED.log.warn('ui-control-panel: Dashboard 2 state store is unavailable')
  }
  return statestore
}

module.exports = function (RED) {
  const base = catalogBase(RED.settings)
  const flowAccess = runtimeFlowAccess(RED)
  const catalogRecovery = base && flowAccess ? createCatalogRecovery({ flowAccess,
    listDevices: () => listCatalogDevices(base),
    onError: error => RED.log.warn('ui-control-panel: catalog recovery deferred: ' + error.message) }) : null
  const activePanels = new Map()
  const activeEditors = new Map()
  const meterRooms = new Map()
  const xySeriesRooms = new Map()
  RED.httpAdmin.get('/ui-control-panel/editor-sync.js', RED.auth.needsPermission('nodes.read'), (_req, res) => {
    res.setHeader('Cache-Control', 'no-store')
    res.sendFile(path.join(__dirname, 'panel-flow-editor-sync.js'))
  })
  RED.httpNode.use((req, res, next) => {
    const path = new URL(req.url, 'http://localhost').pathname
    if (path === '/control-panel-assets/panel-login-bg.png') {
      res.setHeader('Cache-Control', 'public, max-age=86400')
      return res.sendFile(panelLoginImage)
    }
    const editorMatch = path.match(/^\/control-panel-edit\/panels\/([a-zA-Z0-9._-]+)\//)
    if (editorMatch) {
      const editor = activeEditors.get(editorMatch[1])
      if (!editor) return res.status(404).json({ error: 'Visual editor unavailable' })
      return editor.handler(req, res).then(handled => {
        if (!handled) res.status(404).json({ error: 'Not found' })
      }).catch(next)
    }
    const match = path
      .match(/^\/control-panel-api\/panels\/([a-zA-Z0-9._-]+)\//)
    if (!match) return next()
    const gateway = activePanels.get(match[1])
    if (!gateway) return res.status(404).json({ error: 'Panel unavailable' })
    gateway.handler(req, res).then(handled => {
      if (!handled) res.status(404).json({ error: 'Not found' })
    }).catch(next)
  })
  RED.httpAdmin.get('/ui-control-panel/catalog/devices', RED.auth.needsPermission('nodes.read'), async (_req, res) => {
    if (!base) return res.json({ enabled: false, devices: [] })
    try {
      res.json({ enabled: true, devices: await listCatalogDevices(base) })
    } catch (error) {
      res.status(502).json({ error: error.message })
    }
  })
  RED.httpAdmin.post('/ui-control-panel/catalog/targets', RED.auth.needsPermission('nodes.read'), async (req, res) => {
    if (!base) return res.status(404).json({ error: 'Device catalog is unavailable' })
    try {
      res.json({ targets: await listCatalogTargets(base, req.body?.device) })
    } catch (error) {
      res.status(502).json({ error: error.message })
    }
  })
  function ControlPanel (config) {
    const node = this
    RED.nodes.createNode(node, config)

    let parentNode
    const styleOnly = config.templateScope === 'site:style' || config.templateScope === 'page:style'
    const visualBinding = !styleOnly
    let visualBindings = {}
    if (visualBinding) {
      try { visualBindings = parseVisualBindings(config) } catch (error) { node.error(error) }
    }
    const hasVisualBindings = Object.keys(visualBindings).length > 0
    const boundMode = !styleOnly && hasVisualBindings
    const endpoint = `/control-panel-api/panels/${node.id}`
    const boundRoom = config.boundRoom
    let routes
    routes = new Map()
    if (boundMode) {
      try {
        routes = configuredRoutes(config)
      } catch (error) {
        node.error(error)
      }
    }

    const availability = createDeviceAvailability(routes)
    let bridgeReady = !config.bridgeRevisionApplied
    if (config.nativeBridge === true) {
      try {
        bridgeReady = config.bridgeRevisionApplied === managedBridgeRevision({ ...config, id: node.id })
      } catch (error) {
        bridgeReady = false
      }
    }
    node.status?.(bridgeReady ? {} : { fill: 'red', shape: 'ring', text: 'bridge out of sync' })
    const readRefresh = createReadRefresh({ send: identity => {
      if (!boundMode || !bridgeReady) return
      try { node.send({ kind: 'read-all', room: boundRoom, ...(identity.user ? { user: identity.user } : {}) }) }
      catch (error) { node.error(error) }
    } })
    const subscriptionRecovery = createSubscriptionRecovery({ panelId: node.id, flowAccess,
      onError: error => node.warn?.('Subscription recovery deferred: ' + error.message) })

    let meter
    if ([...routes.values()].some(route => route.binding.readMeta?.meter) && /^[a-zA-Z0-9_-]+$/.test(boundRoom || '')) {
      try {
        let hub = meterRooms.get(boundRoom)
        if (!hub) { hub = createMeterRoom({ room: boundRoom }); meterRooms.set(boundRoom, hub) }
        meter = createPanelMeter({ panelId: node.id, room: boundRoom, bindings: visualBindings, hub,
          onSubscribe: () => readRefresh.request() })
      } catch (error) { node.error(error) }
    }

    let xySeries
    if ([...routes.values()].some(route => route.binding.readMeta?.xySeries) && /^[a-zA-Z0-9_-]+$/.test(boundRoom || '')) {
      try {
        let hub = xySeriesRooms.get(boundRoom)
        if (!hub) { hub = createXYSeriesRoom({ room: boundRoom }); xySeriesRooms.set(boundRoom, hub) }
        xySeries = createPanelXYSeries({ panelId: node.id, room: boundRoom, bindings: visualBindings, hub,
          onSubscribe: () => readRefresh.request() })
      } catch (error) { node.error(error) }
    }

    let gateway
    let gatewayAuthKey
    const stopCatalogRecovery = boundMode && config.nativeBridge === true ? catalogRecovery?.attach(node.id,
      [...routes.values()].map(route => route.binding.device), () => readRefresh.request(), device => {
        if (!availability.invalidateDevice(device)) return
        const items = availability.changes()
        if (items) {
          for (const item of items) if (!item.available) momentary.releaseControl(item.id)
          gateway?.boundAvailability(items)
        }
      }) : null
    async function telemetryTicket (req, res, identity, active) {
      if (await meter?.ticket(req, res, identity, active)) return true
      return await xySeries?.ticket(req, res, identity, active) || false
    }
    const momentary = createMomentaryControls({ routes,
      send: (command, identity) => node.send({ ...command, room: identity.room, user: identity.user }),
      onError: error => node.error(error) })
    if (visualBinding && /^[a-zA-Z0-9_-]+$/.test(boundRoom || '')) {
      try {
        gatewayAuthKey = authSignature([node.id, boundRoom, node.credentials?.username,
          node.credentials?.password, config.secureCookie === true])
        gateway = createGateway({
          username: node.credentials?.username,
          password: node.credentials?.password,
          room: boundRoom,
          prefix: endpoint,
          holdEpoch: momentary.epoch,
          secureCookie: config.secureCookie === true,
          restoredSessions: takeSessions(gatewayHandoffs, node.id, gatewayAuthKey),
          onAuthenticatedRequest: (req, res, identity) => telemetryTicket(req, res, identity,
            () => gateway?.sessionActive(identity.token)),
          onBoundCommand: (message, identity) => {
            if (!bridgeReady) return false
            if (message?._controlPanel?.hold?.action !== 'release' && !availability.allowed(message?._controlPanel?.id)) {
              throw Error('Device is unavailable')
            }
            if (message?._controlPanel?.hold) return momentary.handle(message, identity)
            const command = resolveBoundCommand(routes, message)
            if (routes.get(command.controlId)?.control.buttonBehavior === 'momentary' || momentary.isHeld(command)) {
              throw Error('A held button requires the momentary protocol')
            }
            node.send({ ...command, room: identity.room, user: identity.user })
          },
          onSessionClosed: token => momentary.releaseSession(token),
          onBoundLogin: identity => readRefresh.request(identity)
        })
        gateway.boundAvailability(availability.snapshot())
        activePanels.set(node.id, gateway)
      } catch (error) {
        node.error(error)
      }
    } else if (visualBinding) {
      node.error('Visual panel requires a valid room')
    }

    let editor
    let editorAuthKey
    if (visualBinding) {
      editorAuthKey = authSignature([node.id, node.credentials?.editorUsername,
        node.credentials?.editorPassword, config.secureCookie === true])
      editor = createPanelEditor({
        panelId: node.id,
        username: node.credentials?.editorUsername,
        password: node.credentials?.editorPassword,
        secureCookie: config.secureCookie === true,
        restoredSessions: takeSessions(editorHandoffs, node.id, editorAuthKey),
        onAuthenticatedRequest: (req, res, identity) => telemetryTicket(req, res, identity,
          () => editor?.sessionActive(identity.token)),
        onSessionReady: () => readRefresh.request(),
        getConfig: async req => editorConfig(flowAccess ? await flowAccess.getSnapshot()
          : await getSnapshot(req.socket.localPort, undefined,
            RED.settings.httpAdminRoot ?? '/', { maxAgeMs: 5000, allowStaleMs: 60000 }), node.id),
        getDevices: async () => {
          if (!base) throw new Error('Device catalog unavailable')
          return listCatalogDevices(base)
        },
        getTargets: async (_req, device) => {
          if (!base) throw new Error('Device catalog unavailable')
          return listCatalogTargets(base, device)
        },
        apply: (req, body, timing) => applyVisualBindings({
            panelId: node.id,
            rev: body.rev,
            templateHash: body.templateHash,
            entries: body.entries,
            userDir: RED.settings.userDir,
            localPort: req.socket.localPort,
            adminRoot: RED.settings.httpAdminRoot ?? '/',
            catalogBase: base,
            editorCookie: req.headers.cookie,
            flowAccess,
            measure: (name, operation) => timing.measure(name, operation)
          })
      })
      if (editor) activeEditors.set(node.id, editor)
      else node.warn?.('Visual binding editor needs an editor username and password')
    }

    const panelConfig = () => (boundMode || visualBinding) ? {
      endpoint, room: boundRoom, meter: Boolean(meter), xySeries: Boolean(xySeries),
      ...(visualBinding ? { visual: {
        panelId: node.id,
        editorEndpoint: `/control-panel-edit/panels/${node.id}`,
        bindings: visualBindings,
        contract
      } } : {})
    } : null

    const events = {
      onAction: !boundMode,
      ...((meter || xySeries) ? { onSocket: { ...(meter?.hooks || {}), ...(xySeries?.hooks || {}) } } : {}),
      beforeSend (msg) {
        if (msg?._controlPanel?.kind === 'command') throw new Error('Bound commands require authenticated HTTP')
        if (msg?.kind === 'device-availability') {
          if (bridgeReady && gateway) {
            const items = availability.update(msg)
            if (items) {
              for (const item of items) if (!item.available) momentary.releaseControl(item.id)
              const changed = availability.changes()
              if (changed) gateway.boundAvailability(changed)
              // Re-read exported real state after online; no browser refresh,
              // no Deploy and no periodic catalog requests.
              if (msg.payload === true || msg.payload === 'true') readRefresh.request()
            }
          }
          return false
        }
        if (['device-meter-frame', 'device-meter-manifest'].includes(msg?.kind)) {
          if (bridgeReady && meter?.accept(msg)) subscriptionRecovery.accepted(msg)
          // Dashboard 1.31 reads properties before checking whether a message
          // should be emitted. `false` is property-safe and suppresses emit.
          return false
        }
        if (['device-xy-series-frame', 'device-xy-series-manifest'].includes(msg?.kind)) {
          if (bridgeReady && xySeries?.accept(msg)) subscriptionRecovery.accepted(msg)
          return false
        }
        if (boundMode) {
          if (msg?.kind === 'device-feedback' && gateway) {
            const items = availability.feedback(resolveBoundFeedback(routes, msg))
            if (items.length) gateway.boundFeedback(items)
            const changed = availability.changes()
            if (changed) gateway.boundAvailability(changed)
          }
          return {}
        }
        if (msg?.kind === 'device-feedback') {
          return { _controlPanel: { kind: 'states', items: resolveBoundFeedback(routes, msg) } }
        }
        if (msg && msg.ui_update && statestore) {
          const parent = parentNode
          if (parent && typeof msg.ui_update.format !== 'undefined') {
            msg.ui_update.format = injectWidgetPolicy(msg.ui_update.format, config.templateScope,
              panelConfig())
            statestore.set(parent.getBase(), node, msg, 'format', msg.ui_update.format)
          }
        }
        return msg
      }
    }
    if (boundMode) {
      events.onSend = () => { throw new Error('Bound commands require authenticated HTTP') }
    }

    let retryTimer
    let telemetryHooks
    let attempts = 0
    let registered = false

    // Config nodes can be created after this node during a full flow deploy.
    // Retry briefly so a valid group/page is not missed during startup.
    const registerWidget = () => {
      if (registered) return
      const group = config.group ? RED.nodes.getNode(config.group) : null
      const page = !group && config.page ? RED.nodes.getNode(config.page) : null
      const ui = !group && !page && config.ui ? RED.nodes.getNode(config.ui) : null
      if (!group && !page && !ui && attempts++ < 40) {
        retryTimer = setTimeout(registerWidget, 25)
        return
      }

      // Keep the custom editor type in Dashboard's namespace, but use Dashboard's built-in renderer.
      let widgetConfig
      try {
        widgetConfig = {
          ...config,
          type: 'ui-template',
          format: injectWidgetPolicy(config.format, config.templateScope, panelConfig()),
          ...(boundMode ? { passthru: false, storeOutMessages: false, resendOnRefresh: false } : {})
        }
      } catch (error) {
        node.error(error)
        node.status?.({ fill: 'red', shape: 'ring', text: 'visual template unsupported' })
        const message = String(error.message).replace(/[&<>]/g,
          char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[char])
        widgetConfig = { ...config, type: 'ui-template',
          format: '<template><section role="alert" style="padding:24px;color:#a52a35;background:#fff">' +
            '<h2>ControlPanel template error</h2><pre v-pre style="white-space:pre-wrap;overflow-wrap:anywhere">' +
            message + '</pre></section></template>',
          passthru: false, storeOutMessages: false, resendOnRefresh: false }
      }
      parentNode = group || page || ui
      if (meter || xySeries) {
        const baseNode = parentNode?.getBase?.() || parentNode
        telemetryHooks = attachTelemetryHooks({ base: baseNode, panelId: node.id,
          hooks: { ...(meter?.hooks || {}), ...(xySeries?.hooks || {}) } })
        if (telemetryHooks) events.onSocket = { connection: socket => telemetryHooks.connect(socket) }
      }
      if (group) group.register(node, widgetConfig, events)
      else if (page) page.register(null, node, widgetConfig, events)
      else if (ui) ui.register(null, null, node, widgetConfig, events)
      registered = Boolean(parentNode)
      if (registered) readRefresh.request()
    }

    registerWidget()
    node.on('close', () => {
      clearTimeout(retryTimer)
      readRefresh.close()
      subscriptionRecovery.close()
      stopCatalogRecovery?.()
      telemetryHooks?.close()
      momentary.close()
      if (gateway) holdSessions(gatewayHandoffs, node.id, gatewayAuthKey, gateway.sessionSnapshot())
      if (editor) holdSessions(editorHandoffs, node.id, editorAuthKey, editor.sessionSnapshot())
      gateway?.close()
      editor?.close()
      meter?.close()
      xySeries?.close()
      if (meterRooms.get(boundRoom)?.stats().panels === 0) meterRooms.delete(boundRoom)
      if (xySeriesRooms.get(boundRoom)?.stats().panels === 0) xySeriesRooms.delete(boundRoom)
      if (activePanels.get(node.id) === gateway) activePanels.delete(node.id)
      if (activeEditors.get(node.id) === editor) activeEditors.delete(node.id)
    })

  }

  getStateStore(RED)
  RED.nodes.registerType('ui-control-panel', ControlPanel, {
    credentials: {
      username: { type: 'text' }, password: { type: 'password' },
      editorUsername: { type: 'text' }, editorPassword: { type: 'password' }
    }
  })
}
